"""Tests for ToolError."""

import unittest


class TestToolError(unittest.TestCase):
    def test_default_code_is_none(self):
        err = ToolError("test message")
        self.assertIsNone(err.code)

    def test_custom_code_is_kept(self):
        err = ToolError("test message", code="E001")
        self.assertEqual(err.code, "E001")

    def test_str_returns_message(self):
        err = ToolError("test message", code="E001")
        self.assertEqual(str(err), "test message")


if __name__ == "__main__":
    unittest.main()

